import{_ as s,b as n,c as e,g as t}from"./chunks/framework.86O3EbG5.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/23.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/23.md"}'),p={name:"articles/artificial-intelligence/books/AI-modern-approach-homework/23.md"};function i(l,a,o,c,h,d){return n(),e("div",null,[...a[0]||(a[0]=[t(`<p>基于斯图尔特.罗素《人工智能：现代方法（第4版)）》的第 23 章&lt;自然语言处理&gt;，根据此章节的重点，并出一些从 基础→进阶→综合 的练习题，能让我将本章的知识串联起来</p><h2 id="一个三元字符级语言模型-trigram-在训练集中统计到以下计数-忽略句子边界" tabindex="-1">一个三元字符级语言模型（trigram）在训练集中统计到以下计数（忽略句子边界）：</h2><p>&quot;ab&quot; 出现 10 次，其后出现 &#39;c&#39; 5 次，&#39;d&#39; 3 次，&#39;e&#39; 2 次。</p><p>未见过的三元组 &quot;abf&quot; 出现 0 次。 使用拉普拉斯平滑（加1求概率），计算 P(f | &quot;ab&quot;) 和 P(c | &quot;ab&quot;)。假设字母表大小为 26。</p><h2 id="一个-hmm-用于词性标注-状态集-n-v-adj-观测词汇-dog-bark-big-。初始概率-π-n-0-4-π-v-0-3-π-adj-0-3。" tabindex="-1">一个 HMM 用于词性标注，状态集 {N, V, Adj}，观测词汇 {dog, bark, big}。初始概率 π(N)=0.4, π(V)=0.3, π(Adj)=0.3。</h2><p>转移概率：N→N 0.4, N→V 0.3, N→Adj 0.3；V→N 0.5, V→V 0.4, V→Adj 0.1；Adj→N 0.3, Adj→V 0.4, Adj→Adj 0.3。 发射概率（给定词性输出单词）：</p><p>N: dog(0.5), bark(0.3), big(0.2)</p><p>V: dog(0.1), bark(0.7), big(0.2)</p><p>Adj: dog(0.1), bark(0.2), big(0.7) 观测序列：dog bark. 使用维特比算法手工计算最佳词性序列（写出每个状态路径概率）。</p><h2 id="cfg-语法规则" tabindex="-1">CFG 语法规则：</h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>S → NP VP</span></span>
<span class="line"><span>NP → Det N</span></span>
<span class="line"><span>NP → N</span></span>
<span class="line"><span>VP → V NP</span></span>
<span class="line"><span>Det → &#39;the&#39;</span></span>
<span class="line"><span>N → &#39;cat&#39; | &#39;mat&#39;</span></span>
<span class="line"><span>V → &#39;sat&#39;</span></span></code></pre></div><p>给定句子“the cat sat on the mat”不符合此语法（缺少介词短语）。请修改或扩展语法使之能生成该句子（增加规则 PP → P NP, P → &#39;on&#39;, VP → VP PP 等），并画出该句子的句法树。</p><h2 id="cyk-算法-以乔姆斯基范式-cnf-给出下列语法" tabindex="-1">CYK 算法：以乔姆斯基范式（CNF）给出下列语法：</h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>S → NP VP | VP</span></span>
<span class="line"><span>NP → Det N | N</span></span>
<span class="line"><span>VP → V NP | V</span></span>
<span class="line"><span>Det → &#39;the&#39;</span></span>
<span class="line"><span>N → &#39;cat&#39; | &#39;mat&#39;</span></span>
<span class="line"><span>V → &#39;sat&#39; | &#39;on&#39;</span></span></code></pre></div><p>句子：“the cat sat on the mat”。由于 CNF 需要二元拆分，你可能需要先转换为 CNF（假设已转换）。使用 CYK 算法填写表格，判断该句子是否被语法接受。只要描述步骤即可，不要求填完整表格。</p><h2 id="概率-cyk-pcfg-给定-pcfg-规则及其概率" tabindex="-1">概率 CYK（PCFG）：给定 PCFG 规则及其概率：</h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>S → NP VP (1.0)</span></span>
<span class="line"><span>NP → Det N (0.6) | N (0.4)</span></span>
<span class="line"><span>VP → V NP (0.5) | V (0.5)</span></span>
<span class="line"><span>Det → the (1.0)</span></span>
<span class="line"><span>N → cat (0.4) | mat (0.6)</span></span>
<span class="line"><span>V → sat (0.7) | on (0.3)</span></span></code></pre></div><p>句子：“the cat sat”。计算最可能的句法树及其概率（可以采用内部算法计算最大概率树结构）。</p><h2 id="ibm-模型-1-假设平行语料中-英语句子-the-house-与法语句子-la-maison-对齐。词汇翻译表-英语→法语-初始为均匀分布。已知训练语料中-the-与-la-共现3次-the-与-le-共现1次-house-与-maison-共现4次-house-与-maison-也与其他对齐-简化-使用-ibm-模型-1-计算-the-翻译为-la-的概率一次迭代。写出更新公式-不需数字结果-只要解释如何计算-。" tabindex="-1">IBM 模型 1：假设平行语料中，英语句子“the house”与法语句子“la maison”对齐。词汇翻译表（英语→法语）初始为均匀分布。已知训练语料中“the”与“la”共现3次，“the”与“le”共现1次；“house”与“maison”共现4次，“house”与“maison”也与其他对齐？简化：使用 IBM 模型 1 计算“the”翻译为“la”的概率一次迭代。写出更新公式（不需数字结果，只要解释如何计算）。</h2><h2 id="词性标注-hmm-你需要为一种低资源语言-训练数据少-构建词性标注器。" tabindex="-1">词性标注 HMM：你需要为一种低资源语言（训练数据少）构建词性标注器。</h2><p>(1) 解释为什么 HMM 会遇到数据稀疏问题，并提出两种平滑技术。 (2) 除了 HMM，你还可以使用哪些模型？比较它们对标注质量的影响。 (3) 如果只有少量标注数据和大量未标注文本，你会采用什么策略？（提示：半监督学习、自训练）</p><h2 id="句法分析评估-你设计了一个句法分析器-输出一个句子的树结构。" tabindex="-1">句法分析评估：你设计了一个句法分析器，输出一个句子的树结构。</h2><p>(1) 简述精确率（Precision）和召回率（Recall）在句法分析评估中的定义（通常用标记精确率、标记召回率、F1）。 (2) 如果分析器倾向于预测非常小的树（如将所有单词直接挂在根下），精确率和召回率会如何变化？ (3) 如何计算“交叉括号”（crossing brackets）指标？</p><h2 id="机器翻译中的对齐-给定以下双语句对-英语-a-b-c-法语-x-y-z-手动猜测词对齐可能为-a↔x-b↔y-c↔z。" tabindex="-1">机器翻译中的对齐：给定以下双语句对（英语：A B C，法语：X Y Z），手动猜测词对齐可能为 A↔X, B↔Y, C↔Z。</h2><p>(1) 描述 IBM 模型 2 相对于模型 1 增加了什么信息？它如何影响对齐质量？ (2) 如果翻译是“A B”与“Y X”（顺序颠倒），模型 1 能正确对齐吗？模型 2 呢？ (3) 基于短语的翻译系统如何克服词序问题？</p><h2 id="信息抽取系统-你需要从科技新闻中抽取-公司-产品-关系-例如-苹果发布了iphone-。" tabindex="-1">信息抽取系统：你需要从科技新闻中抽取“公司-产品”关系，例如“苹果发布了iPhone”。</h2><p>(1) 设计一个基于模式匹配的方法（写两个模式示例）。 (2) 讨论该方法的优缺点。 (3) 如果想采用监督学习方法，你需要标注什么样的训练数据？设计特征（词性、依赖路径等）。 (4) 如何评估你的抽取系统（准确率、召回率、F1）？</p>`,27)])])}const g=s(p,[["render",i]]);export{b as __pageData,g as default};
